SELECT COUNT(*) AS battery_hv_claims_2023 FROM gishub.fleet.warranty_claims c
INNER JOIN gishub.fleet.vehicles v ON c.vin = v.vin
WHERE c.component = 'battery_hv' AND v.powertrain = 'BEV' AND v.model_year = 2023;

