SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS public_dc_energy_share_pct
FROM gishub.fleet.charging_sessions;

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / NULLIF(SUM(energy_kwh), 0) AS public_dc_energy_share_pct
FROM gishub.fleet.charging_sessions;

SELECT
  COALESCE(100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / NULLIF(SUM(energy_kwh), 0), 0) AS public_dc_energy_share_pct
FROM gishub.fleet.charging_sessions;

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS public_dc_energy_share_pct
